// zod schema for fixtures.json (generated by `python3 tools/verify_gdd.py --export`).
// Test-only, so it lives here and never reaches the app bundle.
import { z } from 'zod';
import {
  FillZone, IllegalCode, ItemOutcome, ItemRef, LevelId, LoadInput, ViolationPair, nonNegInt, posInt,
} from '../engine/schema';

export const FixturesFile = z.strictObject({
  schema: z.literal(1),
  notes: z.string(),
  traps: z.array(z.strictObject({
    name: z.string(),
    load: LoadInput,
    expect: z.strictObject({
      weight: nonNegInt(),
      dryBulk: nonNegInt(),
      wetBulkTenths: nonNegInt(),
      zone: FillZone,
      jam: z.boolean(),
      costMs: posInt(),
      violations: z.array(ViolationPair),
      illegal: z.array(IllegalCode),
    }),
  })),
  illegal: z.array(z.strictObject({ name: z.string(), load: LoadInput, expect: z.array(IllegalCode) })),
  zones: z.array(z.strictObject({ weight: nonNegInt(), dryBulk: nonNegInt(), zone: FillZone })),
  jam: z.array(z.strictObject({ weight: nonNegInt(), wetBulkTenths: nonNegInt(), jam: z.boolean() })),
  cycleCosts: z.array(z.strictObject({ weight: nonNegInt(), dryBulk: nonNegInt(), costMs: posInt() })),
  stars: z.array(z.strictObject({
    violations: z.array(ViolationPair),
    jam: z.boolean(),
    totalMs: nonNegInt(),
    parSeconds: posInt(),
    loads: posInt(),
    minLoads: posInt(),
    stars: z.union([z.literal(0), z.literal(1), z.literal(2), z.literal(3)]),
  })),
  rng: z.strictObject({
    fnv1a32: z.array(z.strictObject({ input: z.string(), hash: nonNegInt() })),
    mulberry32: z.array(z.strictObject({ seed: nonNegInt(), u32: z.array(nonNegInt()) })),
    lostThresholdU32: nonNegInt(),
  }),
  par: z.array(z.strictObject({
    levelId: LevelId,
    itemCount: posInt(),
    multiplierTenths: posInt(),
    sumCostMs: posInt(),
    parSeconds: posInt(),
  })),
  noReuseAlternative43: z.array(LoadInput),
  hamperShuffle: z.array(z.strictObject({
    levelId: LevelId,
    levelSeed: nonNegInt(),
    instanceIdsIn: z.array(ItemRef),
    instanceIdsOut: z.array(ItemRef),
  })),
  consequences: z.array(z.strictObject({
    name: z.string(),
    levelSeed: nonNegInt(),
    loadIndex: nonNegInt(),
    load: LoadInput,
    expect: z.record(ItemRef, ItemOutcome),
  })),
});

export type Fixtures = z.infer<typeof FixturesFile>;
